  '익산에서 부모님 빚이 재산보다 많을지 모른다면. 상속포기와 한정승인의 차이, 상속 개시를 안 날부터 3개월, 특별한정승인, 한정승인 후 공고와 변제 순서, 부당변제 책임을 정리했습니다.',
  '민법 제1019조(승인·포기의 기간, 특별한정승인), 제1032조(채권자에 대한 공고·최고), 제1038조(부당변제 등으로 인한 책임)',
  ['한정승인은 물려받는 재산의 한도에서만 상속채무와 유증을 갚겠다는 신고로, 상속 개시가 있음을 안 날부터 3개월 안에 가정법원에 해야 합니다. 빚이 재산보다 많다는 사실을 중대한 과실 없이 몰랐다면 그 사실을 안 날부터 3개월 안에 특별한정승인을 할 수 있습니다.',
   '한정승인 후에는 5일 안에 채권자와 수증자에게 2개월 이상의 신고기간을 정해 공고하고, 채권자에게 먼저 순서대로 변제한 뒤 남는 재산으로 유증을 이행해야 합니다. 익산 지역 상속 사건은 전주지방법원 군산지원이 관할합니다.'],
