  [('사실관계 정리', '피해 경위와 증거를 시간순으로 정리합니다.'),
   ('고소장 접수', '범죄사실과 입증 계획을 담아 접수합니다.'),
   ('고소인 조사', '진술 흐름과 제출 자료 순서를 정해 조사에 임합니다.'),
   ('보충 · 결과 대응', '반박에 대응하고 처분 결과에 따라 다음 절차를 정합니다.')],
  ['iksan-goso-daeri-chai', 'gunsan-gosoin-josa-daeeung', 'gunsan-sagi-goso-gosojang', 'iksan-bulsongchi-iui-gihan'],
