  ['사기죄는 거짓말로 속여 상대방이 돈을 건네게 하는 범죄라, 돈을 준 다음에 한 거짓말은 아무리 많아도 사기 성립에 영향을 주지 않습니다. 익산경찰서에 고소할 때도 이야기는 돈을 건넨 날에서 끝나도록, 그 전의 말과 사정을 중심으로 정리해야 합니다.',
   '고소당한 쪽이라면 돈을 받을 당시 갚을 의사와 능력이 있었는지가 핵심입니다. 당시 재산·수입 상황과 상환 계획, 실제로 갚은 내역을 자료로 보여 주면 단순한 채무불이행이라는 점을 설명할 수 있습니다.'],
