  '익산에서 형사사건에 연루되었다면. 익산경찰서 조사부터 전주지방공소청 군산지청 처분, 전주지방법원 군산지원 재판까지의 흐름, 혐의없음·기소유예·약식명령·정식 기소의 차이, 변호인 조력이 필요한 사건과 상담으로 충분한 사건, 첫 조사가 중요한 이유, 반성문·합의 시기를 정리했습니다.',
  '형사소송법 제201조의2(영장실질심사와 국선변호인), 제243조의2(변호인 참여), 제244조의5(신뢰관계인 동석), 제245조의5·제245조의7(송치·불송치와 이의신청), 제453조(정식재판 청구)',
  ['익산에서 형사사건 피의자가 되면 대개 익산경찰서에서 조사를 받고, 송치되면 전주지방공소청 군산지청 검사가 혐의없음, 기소유예, 약식기소, 정식 기소 중 처분을 정하며, 재판은 전주지방법원 군산지원에서 열립니다. 2026. 10. 2.부터 공소청 검사는 직접 수사하지 않아 경찰 단계의 진술과 자료가 더 중요해졌습니다.',
   '모든 사건에 변호인 선임이 필요한 것은 아닙니다. 경미한 초범 사건은 상담만으로 충분할 수 있지만, 혐의를 다투거나 합의 여지가 있거나 구속 가능성이 있다면 첫 조사 전부터 준비해야 합니다. 첫 조사에서 작성된 조서는 끝까지 기록에 남기 때문입니다.'],
  [('경찰 단계', '고소인 조사 후 피의자 조사가 잡히고, 송치나 불송치로 마무리됩니다.'),
   ('공소청 처분', '혐의없음, 기소유예, 약식기소, 정식 기소 중 하나가 정해집니다.'),
   ('약식명령 · 항소', '약식명령은 7일 안에 정식재판 청구, 1심 판결은 7일 안에 항소합니다.'),
   ('첫 조사의 무게', '처음 남긴 진술은 바꾸기 어려우니 다툴 사건은 조사 전부터 준비합니다.'),
   ('선임 판단', '경미한 초범 사건은 상담으로 판단하고, 다툼·합의·구속 문제가 있으면 조력을 받습니다.'),
   ('동석과 국선', '성인 조사엔 변호인만 참여하고, 영장실질심사에는 국선변호인이 선정됩니다.')],
