  '익산에서 메시지·SNS로 보낸 내용 때문에 통신매체이용음란 혐의를 받거나 피해를 입었다면. 성적 욕망 목적·통신매체 이용·도달의 세 가지 요건, 말싸움 중 욕설과의 구별, 링크 전송도 도달이 될 수 있다는 판례, 법정형과 합의, 신상정보 등록 문제를 정리했습니다.',
  '성폭력범죄의 처벌 등에 관한 특례법 제13조(통신매체이용음란)',
  ['통신매체이용음란은 성적 욕망을 유발하거나 만족시킬 목적으로 전화·문자·SNS 등 통신매체를 통해 성적 수치심이나 혐오감을 일으키는 말·글·영상 등을 상대방에게 도달하게 하는 범죄로, 2년 이하의 징역 또는 2천만원 이하의 벌금에 처합니다. 세 요건이 모두 충족되어야 하므로 다툰다면 어느 요건이 부족한지부터 따져야 합니다.',
   '말싸움 중 화가 나 성적인 표현이 섞인 욕설을 한 경우처럼 성적 목적이 아니라 모욕 목적이었다면 성립하지 않을 수 있습니다. 반대로 음란물이 있는 사이트 링크만 보내도 상대방이 바로 볼 수 있는 상태가 되었다면 도달로 볼 수 있습니다. 익산 사건은 대개 익산경찰서에서 조사합니다.'],
