  '익산에서 성범죄 혐의로 경찰 조사를 받았거나 앞두고 있다면. 내 진술 조서 확보, 경찰이 요청한 자료 제출, 잘못 답한 부분의 의견서 정정, 고소인 주장 반박 자료, 혐의없음 의견이어도 공소청에 송치되는 전건송치와 송치 후 의견서를 정리했습니다.',
  '형사소송법 제244조(조서 열람·이의), 제245조의5(송치), 성폭력범죄의 처벌 등에 관한 특례법',
  ['성범죄 사건은 진술의 신빙성이 핵심이라 조사 전 준비만큼 조사 뒤 대응이 중요합니다. 조사가 끝났다고 기다리기만 하면 어느 날 송치 통지만 받게 될 수 있으므로, 내 진술 조서를 확보하고 수사관이 요청한 자료를 빠짐없이 내며, 잘못 답한 부분은 의견서로 정정해야 합니다.',
   '익산 사건은 대개 익산경찰서 여성청소년 수사팀에서 조사하고, 성범죄는 경찰이 혐의없음으로 보더라도 전주지방공소청 군산지청에 송치됩니다. 조사 중 알게 된 고소인 주장과 증거를 정리해 반박 자료를 내고, 송치 후에도 검사에게 의견서를 낼 준비를 해 두어야 합니다.'],
