  '익산에서 성범죄 피해를 입고 고소를 준비한다면. 피해자 변호사가 조사·재판에 참여하고 기록을 열람하는 제도, 국선변호사 선정, 합의를 원할 때, 가해자가 혐의를 부인할 때, 시간이 지나 고소할 때의 준비, 피해자 지원 기관을 정리했습니다.',
