   ('미성년자 성매수', '1년 이상 10년 이하 징역 등으로 매우 무겁고 16세 미만은 가중됩니다.'),
   ('수사 방식', '업소 장부, 계좌, 주차 기록 등으로 이용자를 특정합니다.'),
   ('자수', '수사기관이 알기 전이면 감경 사유가 될 수 있습니다.'),
