  '익산에서 협의이혼을 앞두고 있다면. 필수는 아니지만 기한이 있는 위자료와 재산분할, 미성년 자녀가 있으면 반드시 정할 친권자·양육자·양육비·면접교섭, 강제집행이 가능한 양육비부담조서, 숙려기간과 단축·면제를 정리했습니다.',
  '민법 제836조의2(이혼의 절차·숙려기간·양육비부담조서), 제837조(양육), 제839조의2(재산분할 2년)',
