  '익산에서 이혼조정을 신청했거나 조정기일이 잡혔다면. 조정전치주의와 조정 회부, 첫 기일 전 가사조사관의 조기 조사, 상대방이 볼 수 없는 기초조사표, 협의이혼보다 빠르지 않을 수 있는 기일 지정, 조정 단계의 금융거래 조회 신청, 조정 성립의 효력을 정리했습니다.',
