  '익산에서 해고·임금체불·직장 내 괴롭힘이나 징계 문제가 생겼다면. 노동청 진정과 근로감독관 조사, 부당해고 구제신청 3개월, 중앙노동위원회 재심 10일과 행정소송 15일, 형사·민사로 이어지는 경로, 징계위원회 소명과 변호사 동석, 근로자와 사업주가 각각 준비할 자료를 정리했습니다.',
  '근로기준법 제23조(해고 등의 제한), 제27조(해고사유 등의 서면통지), 제28조(부당해고등의 구제신청), 제31조(구제명령 등의 확정), 행정절차법 제12조(대리인)',
  ['노동 분쟁은 노동청 진정이나 노동위원회 구제신청에서 시작해 형사사건, 행정소송, 민사소송으로 이어지는 경우가 많습니다. 첫 단계에서 낸 진술과 자료가 뒤 단계에서도 그대로 쓰이므로, 근로자든 사업주든 처음부터 전체 흐름을 보고 준비해야 합니다.',
   '익산 사업장의 진정은 관할 고용노동지청에서, 부당해고 구제신청은 전북지방노동위원회에서 다루는 경우가 많고, 행정소송과 민사소송은 관할 법원에서 진행합니다. 징계위원회 출석을 앞두고 있다면 변호사 동석이 가능한지 규정을 먼저 확인하고 서면 소명을 준비합니다.'],
  [('노동청 진정', '임금·퇴직금 체불은 근로감독관이 조사하고 형사로 이어질 수 있습니다.'),
   ('구제신청 3개월', '부당해고 등이 있은 날부터 3개월 안에 신청합니다.'),
   ('재심 10일', '지방노동위원회 판정은 10일 안에 재심을 신청합니다.'),
   ('행정소송 15일', '중앙노동위원회 재심판정서 송달 후 15일 안에 소를 냅니다.'),
   ('징계 소명', '징계위원회에서는 서면과 출석으로 소명 기회를 활용합니다.'),
   ('변호사 동석', '사기업은 규정 확인, 행정청 징계는 변호사 출석을 원칙적으로 거부할 수 없습니다.')],
